function drawCharmanderEmberTail(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.4;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.05 * breathSin;
  const sX = 1.0 - 0.025 * breathSin;
  const by = -Math.abs(breathSin) * 3.0;

  const flamePhase = t * 5.0;
  const flameWiggle = Math.sin(flamePhase) * 3.0;

  // Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 42, 26 * (1.0 - 0.15 * breathSin), 6, 0, 0, Math.PI * 2); ctx.fill();

  // Đuôi & ngọn lửa
  ctx.fillStyle = '#f97316';
  ctx.beginPath(); ctx.roundRect(12, by + 20, 16, 6, 3); ctx.fill();
  ctx.beginPath(); ctx.roundRect(22, by + 10, 8, 14, 3); ctx.fill();
  const fx = 26 + flameWiggle;
  const fy = by + 2;
  ctx.fillStyle = '#ef4444';
  ctx.beginPath(); ctx.moveTo(fx - 6, fy + 8); ctx.lineTo(fx, fy - 18); ctx.lineTo(fx + 8, fy + 8); ctx.fill();
  ctx.fillStyle = '#facc15';
  ctx.beginPath(); ctx.moveTo(fx - 4, fy + 6); ctx.lineTo(fx + 2, fy - 12); ctx.lineTo(fx + 6, fy + 6); ctx.fill();

  // Thân cam & bụng kem
  ctx.fillStyle = '#f97316';
  ctx.beginPath(); ctx.ellipse(-2, by + 14, 18 * sX, 16 * sY, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#fef08a';
  ctx.beginPath(); ctx.ellipse(-6, by + 16, 10 * sX, 14 * sY, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#f97316';
  ctx.beginPath(); ctx.roundRect(-16, by + 28, 10, 10, 4); ctx.fill();
  ctx.beginPath(); ctx.roundRect(2,   by + 28, 10, 10, 4); ctx.fill();

  // Đầu cam
  ctx.beginPath(); ctx.ellipse(-4, by - 10, 18 * sX, 16 * sY, 0, 0, Math.PI * 2); ctx.fill();

  // Mắt xanh
  if (!blink) {
    ctx.fillStyle = '#0284c7';
    ctx.beginPath(); ctx.ellipse(-10, by - 10, 4, 7, 0, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.ellipse(4,   by - 10, 4, 7, 0, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(-11, by - 13, 2, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(3,   by - 13, 2, 0, Math.PI * 2); ctx.fill();
  }

  // Miệng & răng
  ctx.fillStyle = '#881337';
  ctx.beginPath(); ctx.moveTo(-4, by + 6); ctx.lineTo(-12, by + 1); ctx.lineTo(4, by + 1); ctx.fill();
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(-10, by + 1, 2, 2);
  ctx.fillRect(2,   by + 1, 2, 2);

  // Tay nhỏ
  ctx.fillStyle = '#f97316';
  ctx.beginPath(); ctx.arc(-14, by + 10, 4, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(8,   by + 10, 4, 0, Math.PI * 2); ctx.fill();

  ctx.restore();
}
